package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class QuantityAsFractionTest {
 @Test public void declaredFractionChoicesRemainFractionsForIntegerResults(){for(boolean decimal:new boolean[]{false,true}){Question q=QuantityAsFraction.make(100,25,"kg");q.decimal=decimal;Choices.build(q,Catalog.get(q.skillId),new Random(283));assertEquals(4,q.choices.size());assertTrue(q.choices.stream().allMatch(c->c.matches("[+-]?\\d+/\\d+")));assertTrue(new Checker().check(q,List.of(),List.of(q.choices.get(q.correctChoice))).correct());}}
 @Test public void officialExampleAndOrderArePublic(){Question q=QuantityAsFraction.make(5,25,"kg");q.expression="999";q.answers[0]="999";assertTrue(new Checker().check(q,List.of(),List.of("1/5")).correct());assertTrue(new Checker().check(q,List.of(),List.of("5/25")).correct());assertFalse(new Checker().check(q,List.of(),List.of("5/1")).correct());assertFalse(new Checker().check(q,List.of(),List.of("0.2")).correct());HelpPlan h=HelpPlan.forQuestion(q);assertEquals(5,h.size());assertFalse(h.canTransfer());for(int i=0;i<5;i++){assertTrue(h.step(i).accepts(List.of("5","25","5","1","5").get(i)));assertEquals("",h.step(i).after);}assertEquals(1,FractionInput.errorPart(q,"2/5"));assertEquals(2,FractionInput.errorPart(q,"1/6"));}
 @Test public void zeroEqualityImproperAndUnitsKeepTheirMeaning(){for(int[] pair:new int[][]{{0,100},{100,100},{100,1},{25,5}}){Question q=QuantityAsFraction.make(pair[0],pair[1],"m");assertTrue(new Checker().check(q,List.of(),List.of(pair[0]+"/"+pair[1])).correct());assertTrue(FractionInput.defaultFraction(q));}Question q=QuantityAsFraction.make(5,25,"kg");assertEquals(Rational.of(200),QuantityAsFraction.read(new Question(q.skillId,q.prompt.replace("25 kg","25 g"),"poison","999")).value());for(int[] p:new int[][]{{-1,2},{101,2},{1,0},{1,101}}){try{QuantityAsFraction.make(p[0],p[1],"kg");fail();}catch(IllegalArgumentException expected){}}}
 @Test public void normalNaSixHasFreshAllUnitRatios(){var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade(QuantityAsFraction.ID,6));assertFalse(pack.inGrade(QuantityAsFraction.ID,5));Generator g=new Generator(new Random(283));var limits=GlobalCurriculum.limits(pack.id,QuantityAsFraction.ID,6);List<String> recent=new ArrayList<>();Set<String> units=new HashSet<>();boolean improper=false;for(int i=0;i<150;i++){Question q=g.next(QuantityAsFraction.ID,recent,i%2==0,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=QuantityAsFraction.read(q);assertNotNull(v);units.add(v.unit());improper|=v.first().compareTo(v.second())>0;assertTrue(limits.allows(q));if(!q.choices.isEmpty()){assertEquals(4,q.choices.size());assertTrue(new Checker().check(q,List.of(),List.of(q.choices.get(q.correctChoice))).correct());assertTrue(q.choices.stream().allMatch(c->c.contains("/")));assertTrue(q.choices.stream().allMatch(c->Expression.number(c).compareTo(Rational.ZERO)>=0&&Expression.number(c).compareTo(Rational.of(100))<=0));}assertTrue(new Checker().check(q,List.of(),List.of(v.first()+"/"+v.second())).correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());}assertEquals(Set.of("kg","m","L"),units);assertTrue(improper);}
}
